UPDATE news_items SET item_type = 'community', source_name = CASE WHEN source_url LIKE '%linkedin.com%' THEN 'LinkedIn' WHEN source_url LIKE '%reddit.com%' THEN 'Reddit' WHEN source_url LIKE '%youtube.com%' THEN 'YouTube' WHEN source_url LIKE '%twitter.com%' OR source_url LIKE '%x.com%' THEN 'X/Twitter' ELSE source_name END WHERE (source_url LIKE '%linkedin.com%' OR source_url LIKE '%reddit.com%' OR source_url LIKE '%twitter.com%' OR source_url LIKE '%x.com%' OR source_url LIKE '%youtube.com%' OR source_url LIKE '%quora.com%') AND item_type = 'news';